/**
 * A histogram showing the distribution of one sample (`design/components/histogram.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/histogram.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  DEFAULT_CHART_MESSAGES,
  Each,
  UNMEASURED,
  agentMember,
  chartMarks,
  chartPosition,
  chooseChartMark,
  claimSlot,
  createCell,
  createDerived,
  createReading,
  createWarningLog,
  devWarning,
  elementRef,
  histogramModel,
  histogramReadout,
  histogramSelection,
  measureBox,
  nearestIndex,
  readChartPosition,
  readingRest,
  readingView,
  scope,
  watchEffect,
  type ChartMessages,
  type ChartTooltipConfig,
  type ChartYAxis,
  type Defaults,
  type HistogramXAxis,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/charts/histogram.module.css'
import a11y from '@polymorph/recipes/conventions/a11y.module.css'
import chartAxis from '@polymorph/recipes/charts/frame/chart-axis.module.css'
import chartFrame from '@polymorph/recipes/charts/frame/chart-frame.module.css'
import chartTooltip from '@polymorph/recipes/charts/frame/chart-tooltip.module.css'
import chartTwin from '@polymorph/recipes/charts/frame/chart-twin.module.css'
import Button from '../controls/Button'
import Table from '../structure/Table'
import TableBody from '../structure/TableBody'
import TableCell from '../structure/TableCell'
import TableHead from '../structure/TableHead'
import TableHeader from '../structure/TableHeader'
import TableRow from '../structure/TableRow'

export interface HistogramProps {
  /**
   * A **target** bin count. Defaults to d3's Sturges rule (⌈log₂ n⌉ + 1). `d3-array.bin` may
   * adjust it to clean thresholds, as tick counts are.
   */
  bins?: number
  /**
   * The raw observations, unbinned and in any order; `[]` renders the empty state.
   */
  data: readonly number[]
  /**
   * The accessible name.
   */
  label: string
  /**
   * Shows the previous frame at reduced opacity during a refetch.
   */
  loading?: boolean
  /**
   * The locale for `Intl` formatting.
   */
  locale?: string
  /**
   * The chart tier's string catalog (`ChartMessages`). Defaults to generic English; a localized
   * host passes the same object to every chart.
   */
  messages?: ChartMessages
  /**
   * Called with the read bin's edges and count, on Enter, Space or click.
   */
  onSelect?: (selection: { bin: { from: number; to: number; count: number } }) => void
  size?: 'sm' | 'md' | 'lg'
  /**
   * The per-bin readout: the range and its count. `false` removes the visual layer only.
   */
  tooltip?: false | ChartTooltipConfig
  /**
   * The measure's axis. It is not a `ChartXAxis`: there is no `key`, because the sample is the
   * column, and no `scale`, because it is always linear. Ticks sit at bin edges, thinned to
   * clean steps.
   */
  x?: HistogramXAxis
  /**
   * The count axis, **always zero-anchored** because a truncated bar misstates a count. `domain:
   * 'auto'` raises a dev warning and is ignored, as in BarChart.
   */
  y?: ChartYAxis
}

/** A histogram showing the distribution of one sample. */
export default function Histogram(given: HistogramProps): JSX.Element {
  const props = mergeProps(
    {
      size: 'md',
      tooltip: (() => ({}))(),
      loading: false,
      messages: (() => DEFAULT_CHART_MESSAGES)(),
    } as Defaults<HistogramProps, 'size' | 'tooltip' | 'loading' | 'messages'>,
    claimSlot(given),
  )
  return scope(() => {
    const box = createCell(UNMEASURED)
    const reading = createCell(createReading({ count: 0, seriesStart: null }))
    const position = createCell(readingRest(null))
    const twinOpen = createCell(false)
    const warningLog = createCell(createWarningLog())
    const frame = elementRef<HTMLElement>()
    const plot = elementRef<HTMLElement>()
    const input = createDerived(() => ({
      data: props.data,
      bins: props.bins,
      x: props.x,
      y: props.y,
      label: props.label,
      locale: props.locale,
      messages: props.messages,
      tooltip: props.tooltip,
      loading: props.loading,
      selectable: props.onSelect !== undefined,
      box: box.value,
    }))
    const model = createDerived(() => histogramModel(input.value))
    const view = createDerived(() => readingView(position.value, model.value.bins.length))
    const readout = createDerived(() => histogramReadout(input.value, model.value, view.value))
    const activate = createDerived(() => () => {
      const selection = histogramSelection(input.value, model.value, reading.value.now())
      if (selection !== null) props.onSelect?.(selection)
    })
    const walk = createDerived(() => ({ count: model.value.bins.length }))
    const marks = createDerived(() => ({
      walk: walk.value,
      input: input.value,
      model: model.value,
      readout: histogramReadout,
      selection: histogramSelection,
    }))
    const onKey = createDerived(() => (event: KeyboardEvent) => {
      if (props.onSelect !== undefined && (event.key === 'Enter' || event.key === ' ')) {
        event.preventDefault()
        activate.value()
        return
      }
      reading.value.update(walk.value)
      if (reading.value.key(event.key)) event.preventDefault()
    })
    const onPointer = createDerived(() => (event: PointerEvent) => {
      if (model.value.plot === null) return
      const rect = (event.currentTarget as Element).getBoundingClientRect()
      reading.value.moveTo(nearestIndex(model.value.positions, event.clientX - rect.left))
    })
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const run = () => {
        box.value = plot.value === null ? box.value : measureBox(plot.value, box.value)
      }
      const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
      for (const element of [plot.value]) if (element) resize?.observe(element)
      release1 = () => {
        resize?.disconnect()
      }
      run()
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    const effect2 = () => {
      reading.value.subscribe((now) => {
        position.value = now
      })
    }
    onMount(effect2)
    const effect3 = () => {
      warningLog.value.log(model.value.warnings, (message) => devWarning(true, message))
    }
    watchEffect(
      createMemo(() => model.value.warnings.join('\n')),
      effect3,
      true,
    )
    let release4: (() => void) | undefined
    const effect4 = () => {
      release4?.()
      const ran = !(props.onSelect !== undefined)
        ? () => {}
        : agentMember({
            member: 'Histogram',
            element: () => frame.value,
            state: () => ({
              items: chartMarks(marks.value, reading.value),
              position: chartPosition(marks.value, reading.value),
              count: walk.value.count,
            }),
            actions: {
              read: {
                argument: 'number',
                run: (value) => readChartPosition(marks.value, value, reading.value),
              },
              choose: {
                argument: 'id',
                run: (value) => chooseChartMark(marks.value, value, reading.value, activate.value),
              },
            },
          })
      release4 = () => {
        ran()
      }
    }
    onMount(effect4)
    onCleanup(() => release4?.())
    return (
      <figure
        class={chartFrame.frame}
        data-size={props.size}
        data-state={model.value.state}
        data-position={view.value.active ? view.value.index : undefined}
        aria-label={props.label}
        data-member="histogram"
        ref={frame.attach}
      >
        {/* region */}
        <div class={chartFrame.region}>
          {/* y axis */}
          <div class={chartFrame.yAxis}>
            {model.value.axes?.y !== undefined ? (
              <div class={chartAxis.axis} data-orientation="y" aria-hidden="true">
                <Each of={model.value.axes?.y ?? []} by={(tick) => tick.key} renew>
                  {(tick) => (
                    <span
                      class={chartAxis.tick}
                      style={{ top: `${tick.at}px` }}
                      data-align={tick.align}
                    >
                      {tick.label}
                    </span>
                  )}
                </Each>
              </div>
            ) : null}
          </div>
          {/* plot */}
          <div class={chartFrame.plot} ref={plot.attach}>
            {model.value.state === 'empty' ? (
              <div class={chartFrame.empty}>
                <span>{props.messages.empty}</span>
              </div>
            ) : (
              <div
                class={styles.surface}
                tabindex="0"
                role="img"
                aria-label={props.label}
                onkeydown={($event: KeyboardEvent) => onKey.value($event)}
                onclick={() => activate.value()}
                onpointermove={($event: PointerEvent) => onPointer.value($event)}
                onpointerleave={() => reading.value.clear()}
                onblur={() => reading.value.clear()}
              >
                {model.value.plot !== null ? (
                  <svg
                    class={styles.marks}
                    style={{ '--pm-chart-zero': `${model.value.plot?.zero}px` }}
                    data-reading={view.value.active ? '' : undefined}
                    width={model.value.plot?.width}
                    height={model.value.plot?.height}
                    aria-hidden="true"
                    {...{ focusable: 'false' }}
                  >
                    {/* grid */}
                    <g class={styles.grid}>
                      <Each of={model.value.plot?.grid ?? []} by={(line) => line.key} renew>
                        {(line) => <path d={line.d} />}
                      </Each>
                    </g>
                    {/* bins */}
                    <g class={styles.bins}>
                      <Each of={model.value.plot?.bars ?? []} by={(bar) => bar.key} renew>
                        {(bar) => (
                          <g data-active={view.value.index === bar.index ? '' : undefined}>
                            <rect
                              class={styles.hit}
                              x={bar.hit.x}
                              y={bar.hit.y}
                              width={bar.hit.width}
                              height={bar.hit.height}
                              onpointerenter={() => reading.value.moveTo(bar.index)}
                            />
                            {bar.d !== null ? (
                              <path class={styles.bar} d={bar.d ?? undefined} />
                            ) : null}
                          </g>
                        )}
                      </Each>
                    </g>
                    {/* zero */}
                    <path class={styles.zero} d={model.value.plot?.zeroRule} />
                  </svg>
                ) : null}
              </div>
            )}
            {readout.value.tooltip !== null ? (
              <div
                class={chartTooltip.tooltip}
                style={{
                  '--pm-chart-tip-x': `${readout.value.tooltip?.x}px`,
                  '--pm-chart-tip-y': `${readout.value.tooltip?.y}px`,
                }}
                data-indicator={readout.value.tooltip?.indicator}
                data-side={readout.value.tooltip?.side}
                aria-hidden="true"
              >
                {readout.value.tooltip?.header !== undefined ? (
                  <p class={chartTooltip.header}>{readout.value.tooltip?.header}</p>
                ) : null}
                <ul class={chartTooltip.rows}>
                  <Each of={readout.value.tooltip?.rows ?? []} by={(row) => row.key} renew>
                    {(row) => (
                      <li class={chartTooltip.row}>
                        <span class={chartTooltip.key} style={{ '--pm-chart-key': row.paint }} />
                        <span class={chartTooltip.value}>{row.value}</span>
                        <span class={chartTooltip.label}>{row.label}</span>
                      </li>
                    )}
                  </Each>
                </ul>
              </div>
            ) : null}
          </div>
          {/* x axis */}
          <div class={chartFrame.xAxis}>
            {model.value.axes?.x !== undefined ? (
              <div class={chartAxis.axis} data-orientation="x" aria-hidden="true">
                <Each of={model.value.axes?.x ?? []} by={(tick) => tick.key} renew>
                  {(tick) => (
                    <span
                      class={chartAxis.tick}
                      style={{ left: `${tick.at}px` }}
                      data-align={tick.align}
                    >
                      {tick.label}
                    </span>
                  )}
                </Each>
              </div>
            ) : null}
          </div>
        </div>
        {/* summary */}
        <span class={a11y.visuallyHidden}>{model.value.summary}</span>
        {/* twin */}
        <div class={chartTwin.twin} data-state={twinOpen.value ? 'open' : 'closed'}>
          <div class={chartTwin.toggle}>
            <Button
              variant="ghost"
              tone="neutral"
              size="sm"
              icon="table"
              iconOnly={true}
              label={
                twinOpen.value
                  ? props.messages.hideTable(props.label)
                  : props.messages.showTable(props.label)
              }
              onClick={() => (twinOpen.value = !twinOpen.value)}
            />
          </div>
          {twinOpen.value ? (
            <div class={chartTwin.table}>
              <Table
                label={props.messages.tableLabel(props.label)}
                caption={props.messages.tableLabel(props.label)}
              >
                <TableHead>
                  <TableRow>
                    <Each of={model.value.twin.columns} by={(column) => column.key} renew>
                      {(column) => (
                        <TableHeader numeric={column.numeric}>{column.label}</TableHeader>
                      )}
                    </Each>
                  </TableRow>
                </TableHead>
                <TableBody>
                  <Each of={model.value.twin.rows} by={(_row, line) => line} renew>
                    {(row) => (
                      <TableRow>
                        <Each
                          of={row}
                          by={(_cell, cellIndex) =>
                            model.value.twin.columns[cellIndex]?.key ?? cellIndex
                          }
                          renew
                        >
                          {(cell, cellIndex) => (
                            <TableCell numeric={model.value.twin.columns[cellIndex()]?.numeric}>
                              {cell === '' ? '—' : cell}
                            </TableCell>
                          )}
                        </Each>
                      </TableRow>
                    )}
                  </Each>
                </TableBody>
              </Table>
            </div>
          ) : null}
        </div>
        {/* live region */}
        <span class={a11y.visuallyHidden}>
          <div aria-live="polite" aria-atomic="true">
            {readout.value.announcement}
          </div>
        </span>
      </figure>
    )
  })
}
